SELECT IF(c.np + c.na + c.ns + (c.ayh <> '') + (c.ibu <> '') = 0, '<mark>susunan ahli waris belum diisi - isi variabel 9701 s.d. 9704 dan 9718</mark>', CONCAT_WS('<br>', IF(c.np = 0, NULL, CONCAT('Menimbang, bahwa ', IF(LOCATE(';', c.pas) = 0, c.pas, CONCAT(REPLACE(SUBSTRING_INDEX(c.pas, ';', (LENGTH(c.pas) - LENGTH(REPLACE(c.pas, ';', '')) + 1) - 1), ';', ','), ' dan ', TRIM(SUBSTRING_INDEX(c.pas, ';', -1)))), ' berkedudukan sebagai ', IF(c.sx = 'P', 'duda', 'janda'), ' Pewaris, sehingga berdasarkan Pasal ', IF(c.sx = 'P', '179', '180'), ' Kompilasi Hukum Islam mendapat bagian ', IF(c.sx = 'P', IF(c.na > 0, 'seperempat (1/4)', 'separuh (1/2)'), IF(c.na > 0, 'seperdelapan (1/8)', 'seperempat (1/4)')), IF(c.np > 1, ' yang dibagi sama rata di antara mereka', ''), ' karena Pewaris ', IF(c.na > 0, 'meninggalkan anak', 'tidak meninggalkan anak'), ';')), IF(c.na = 0, NULL, CASE WHEN c.nap = 0 THEN CONCAT('Menimbang, bahwa Pewaris meninggalkan ', c.na, ' orang anak laki-laki yaitu ', IF(LOCATE(';', c.ank) = 0, c.ank, CONCAT(REPLACE(SUBSTRING_INDEX(c.ank, ';', (LENGTH(c.ank) - LENGTH(REPLACE(c.ank, ';', '')) + 1) - 1), ';', ','), ' dan ', TRIM(SUBSTRING_INDEX(c.ank, ';', -1)))), ', yang berkedudukan sebagai ashabah sehingga memperoleh sisa harta peninggalan setelah diambil bagian ahli waris dzawil furud lainnya, dan dibagi sama rata di antara mereka bila lebih dari seorang;') WHEN c.nap = c.na AND c.na = 1 THEN CONCAT('Menimbang, bahwa Pewaris meninggalkan seorang anak perempuan yaitu ', IF(LOCATE(';', c.ank) = 0, c.ank, CONCAT(REPLACE(SUBSTRING_INDEX(c.ank, ';', (LENGTH(c.ank) - LENGTH(REPLACE(c.ank, ';', '')) + 1) - 1), ';', ','), ' dan ', TRIM(SUBSTRING_INDEX(c.ank, ';', -1)))), ', sehingga berdasarkan Pasal 176 Kompilasi Hukum Islam anak perempuan yang hanya seorang mendapat separuh (1/2) bagian;') WHEN c.nap = c.na THEN CONCAT('Menimbang, bahwa Pewaris meninggalkan ', c.na, ' orang anak perempuan yaitu ', IF(LOCATE(';', c.ank) = 0, c.ank, CONCAT(REPLACE(SUBSTRING_INDEX(c.ank, ';', (LENGTH(c.ank) - LENGTH(REPLACE(c.ank, ';', '')) + 1) - 1), ';', ','), ' dan ', TRIM(SUBSTRING_INDEX(c.ank, ';', -1)))), ', sehingga berdasarkan Pasal 176 Kompilasi Hukum Islam anak perempuan yang berjumlah dua orang atau lebih bersama-sama mendapat dua pertiga (2/3) bagian;') ELSE CONCAT('Menimbang, bahwa Pewaris meninggalkan ', c.na - c.nap, ' orang anak laki-laki dan ', c.nap, ' orang anak perempuan yaitu ', IF(LOCATE(';', c.ank) = 0, c.ank, CONCAT(REPLACE(SUBSTRING_INDEX(c.ank, ';', (LENGTH(c.ank) - LENGTH(REPLACE(c.ank, ';', '')) + 1) - 1), ';', ','), ' dan ', TRIM(SUBSTRING_INDEX(c.ank, ';', -1)))), ', sehingga berdasarkan Pasal 176 Kompilasi Hukum Islam apabila anak perempuan bersama-sama dengan anak laki-laki maka bagian anak laki-laki adalah dua banding satu dengan anak perempuan, dan mereka memperoleh sisa harta peninggalan setelah diambil bagian ahli waris dzawil furud lainnya;') END), IF(c.ayh = '', NULL, CONCAT('Menimbang, bahwa ', c.ayh, ' adalah ayah kandung Pewaris yang masih hidup, sehingga berdasarkan Pasal 177 Kompilasi Hukum Islam mendapat ', IF(c.na > 0, 'seperenam (1/6)', 'sepertiga (1/3)'), ' bagian karena Pewaris ', IF(c.na > 0, 'meninggalkan anak', 'tidak meninggalkan anak'), ';')), IF(c.ibu = '', NULL, CONCAT('Menimbang, bahwa ', c.ibu, ' adalah ibu kandung Pewaris yang masih hidup, sehingga berdasarkan Pasal 178 Kompilasi Hukum Islam mendapat ', IF(c.na > 0, 'seperenam (1/6) bagian karena Pewaris meninggalkan anak', IF(c.ns >= 2, 'seperenam (1/6) bagian karena Pewaris meninggalkan dua saudara atau lebih', IF(c.np > 0 AND c.ayh <> '', 'sepertiga (1/3) bagian dari sisa sesudah diambil bagian janda atau duda karena bersama-sama dengan ayah', 'sepertiga (1/3) bagian karena Pewaris tidak meninggalkan anak'))), ';')), IF(c.ns = 0, NULL, IF(c.na > 0 OR c.ayh <> '', CONCAT('Menimbang, bahwa karena Pewaris meninggalkan ', IF(c.na > 0, 'anak', 'ayah'), ', maka bagian saudara Pewaris (', IF(LOCATE(';', c.sdr) = 0, c.sdr, CONCAT(REPLACE(SUBSTRING_INDEX(c.sdr, ';', (LENGTH(c.sdr) - LENGTH(REPLACE(c.sdr, ';', '')) + 1) - 1), ';', ','), ' dan ', TRIM(SUBSTRING_INDEX(c.sdr, ';', -1)))), ') tidak ditentukan secara otomatis, karena Pasal 182 Kompilasi Hukum Islam mensyaratkan Pewaris tidak meninggalkan anak dan ayah, dan hal tersebut dipertimbangkan tersendiri oleh Majelis Hakim;'), CASE WHEN c.nsp = 0 THEN CONCAT('Menimbang, bahwa Pewaris tidak meninggalkan anak dan ayah, sedangkan saudara-saudara Pewaris yaitu ', IF(LOCATE(';', c.sdr) = 0, c.sdr, CONCAT(REPLACE(SUBSTRING_INDEX(c.sdr, ';', (LENGTH(c.sdr) - LENGTH(REPLACE(c.sdr, ';', '')) + 1) - 1), ';', ','), ' dan ', TRIM(SUBSTRING_INDEX(c.sdr, ';', -1)))), ' adalah saudara laki-laki kandung atau seayah sehingga berkedudukan sebagai ashabah dan memperoleh sisa harta peninggalan setelah diambil bagian ahli waris dzawil furud lainnya;') WHEN c.nsp = c.ns AND c.ns = 1 THEN CONCAT('Menimbang, bahwa Pewaris tidak meninggalkan anak dan ayah, sehingga berdasarkan Pasal 182 Kompilasi Hukum Islam saudara perempuan kandung atau seayah yang hanya seorang, yaitu ', IF(LOCATE(';', c.sdr) = 0, c.sdr, CONCAT(REPLACE(SUBSTRING_INDEX(c.sdr, ';', (LENGTH(c.sdr) - LENGTH(REPLACE(c.sdr, ';', '')) + 1) - 1), ';', ','), ' dan ', TRIM(SUBSTRING_INDEX(c.sdr, ';', -1)))), ', mendapat separuh (1/2) bagian;') WHEN c.nsp = c.ns THEN CONCAT('Menimbang, bahwa Pewaris tidak meninggalkan anak dan ayah, sehingga berdasarkan Pasal 182 Kompilasi Hukum Islam saudara perempuan kandung atau seayah yang berjumlah dua orang atau lebih, yaitu ', IF(LOCATE(';', c.sdr) = 0, c.sdr, CONCAT(REPLACE(SUBSTRING_INDEX(c.sdr, ';', (LENGTH(c.sdr) - LENGTH(REPLACE(c.sdr, ';', '')) + 1) - 1), ';', ','), ' dan ', TRIM(SUBSTRING_INDEX(c.sdr, ';', -1)))), ', bersama-sama mendapat dua pertiga (2/3) bagian;') ELSE CONCAT('Menimbang, bahwa Pewaris tidak meninggalkan anak dan ayah, sehingga berdasarkan Pasal 182 Kompilasi Hukum Islam saudara perempuan bersama saudara laki-laki kandung atau seayah, yaitu ', IF(LOCATE(';', c.sdr) = 0, c.sdr, CONCAT(REPLACE(SUBSTRING_INDEX(c.sdr, ';', (LENGTH(c.sdr) - LENGTH(REPLACE(c.sdr, ';', '')) + 1) - 1), ';', ','), ' dan ', TRIM(SUBSTRING_INDEX(c.sdr, ';', -1)))), ', memperoleh bagian dengan perbandingan saudara laki-laki dua banding satu dengan saudara perempuan;') END)), 'Menimbang, bahwa bagian-bagian tersebut diuraikan sebagai dasar pertimbangan penetapan ahli waris;penghitungan bagian masing-masing ahli waris atas harta peninggalan dilakukan pada saat harta peninggalan dibagi, dengan memperhatikan jumlah ahli waris yang ada dan keadaan harta peninggalan;')) AS data FROM (SELECT i.*, IF(i.pas = '', 0, LENGTH(i.pas) - LENGTH(REPLACE(i.pas, ';', '')) + 1) AS np, IF(i.ank = '', 0, LENGTH(i.ank) - LENGTH(REPLACE(i.ank, ';', '')) + 1) AS na, ROUND((LENGTH(LOWER(i.ank)) - LENGTH(REPLACE(LOWER(i.ank), ' binti ', ''))) / 7) AS nap, IF(i.sdr = '', 0, LENGTH(i.sdr) - LENGTH(REPLACE(i.sdr, ';', '')) + 1) AS ns, ROUND((LENGTH(LOWER(i.sdr)) - LENGTH(REPLACE(LOWER(i.sdr), ' binti ', ''))) / 7) AS nsp FROM (SELECT TRIM(TRAILING ';' FROM TRIM(IFNULL(REPLACE(REPLACE(REPLACE(CONVERT((SELECT data FROM aps_badilag.abt_data_teks WHERE no_var = 9701 AND perkara_id = '#perkara_id#' LIMIT 1) USING utf8), '\\', '/'), '"', '&quot;'), '''', '&#39;'), ''))) AS pas, TRIM(TRAILING ';' FROM TRIM(IFNULL(REPLACE(REPLACE(REPLACE(CONVERT((SELECT data FROM aps_badilag.abt_data_teks WHERE no_var = 9702 AND perkara_id = '#perkara_id#' LIMIT 1) USING utf8), '\\', '/'), '"', '&quot;'), '''', '&#39;'), ''))) AS ank, TRIM(TRAILING ';' FROM TRIM(IFNULL(REPLACE(REPLACE(REPLACE(CONVERT((SELECT data FROM aps_badilag.abt_data_teks WHERE no_var = 9703 AND perkara_id = '#perkara_id#' LIMIT 1) USING utf8), '\\', '/'), '"', '&quot;'), '''', '&#39;'), ''))) AS ayh, TRIM(TRAILING ';' FROM TRIM(IFNULL(REPLACE(REPLACE(REPLACE(CONVERT((SELECT data FROM aps_badilag.abt_data_teks WHERE no_var = 9704 AND perkara_id = '#perkara_id#' LIMIT 1) USING utf8), '\\', '/'), '"', '&quot;'), '''', '&#39;'), ''))) AS ibu, IF(IFNULL(CONVERT((SELECT data FROM aps_badilag.abt_data_teks WHERE no_var = 1025 AND perkara_id = '#perkara_id#' LIMIT 1) USING utf8), '') LIKE '%binti%', 'P', 'L') AS sx, TRIM(TRAILING ';' FROM TRIM(IFNULL(REPLACE(REPLACE(REPLACE(CONVERT((SELECT data FROM aps_badilag.abt_data_teks WHERE no_var = 9700 AND perkara_id = '#perkara_id#' LIMIT 1) USING utf8), '\\', '/'), '"', '&quot;'), '''', '&#39;'), ''))) AS dana, TRIM(TRAILING ';' FROM TRIM(IFNULL(REPLACE(REPLACE(REPLACE(CONVERT((SELECT data FROM aps_badilag.abt_data_teks WHERE no_var = 9718 AND perkara_id = '#perkara_id#' LIMIT 1) USING utf8), '\\', '/'), '"', '&quot;'), '''', '&#39;'), ''))) AS sdr) i) c